function normalizeKey(r) {
  const text = ((r.gp || '') + ' ' + (r.tor || ''))
    .toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  const dict = [
    ['thailand', ['thai', 'tajlandi', 'buriram', 'chang international']],
    ['argentina', ['argentin', 'buenos aires', 'galvez']],
    ['australia', ['australi', 'adelaide', 'phillip island']],
    ['aragon', ['aragon', 'motorland', 'alcaniz']],
    ['malaysia', ['malaysia', 'malezj', 'sepang']],
    ['americas', ['americas', 'ameryk', 'austin', 'cota']],
    ['catalunya', ['catalu', 'barcelona', 'montmelo']],
    ['france', ['france', 'francj', 'le mans']],
    ['italy', ['italy', 'wloch', 'mugello']],
    ['sanmarino', ['san marino', 'misano']],
    ['japan', ['japan', 'japoni', 'motegi']],
    ['indonesia', ['indonesi', 'mandalika']],
    ['valencia', ['valencia', 'ricardo tormo']],
    ['austria', ['austri', 'red bull ring', 'spielberg']],
    ['jerez', ['jerez']],
    ['monaco', ['monaco', 'monako']],
    ['qatar', ['qatar', 'katar', 'losail']],
    ['portugal', ['portugal', 'estoril']],
    ['netherlands', ['assen', 'netherland', 'holandi']],
    ['germany', ['sachsenring', 'niemc']],
    ['britain', ['silverstone', 'brytani']],
    ['hungary', ['hungary', 'weg', 'balaton']]
  ];
  for (const [key, patterns] of dict) {
    if (patterns.some(p => text.includes(p))) return key;
  }
  return (r.gp || 'unknown').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z]/g,'');
}
const text = $json.choices[0].message.content;

let parsed;
try {
  parsed = JSON.parse(text);
  if (Array.isArray(parsed)) parsed = parsed[0];
} catch (e) {
  return [{ json: { should_send: false, message_pl: '', known_rounds_json: '[]', debug_error: e.message, debug_text: text.substring(0, 500) } }];
}

async function getPreviousRounds() {
  try {
    const prevItem = $('Odczyt stanu z pliku').item;
    let raw;
    if (prevItem.binary && prevItem.binary.data) {
      const buffer = await this.helpers.binaryToBuffer(prevItem.binary.data);
      raw = buffer.toString('utf8');
    } else if (prevItem.json && prevItem.json.stdout) {
      raw = prevItem.json.stdout;
    } else {
      raw = JSON.stringify(prevItem.json);
    }
    let arr = JSON.parse(raw);
    if (arr && arr.known_rounds_json) arr = JSON.parse(arr.known_rounds_json);
    return Array.isArray(arr) ? arr : [];
  } catch (e) {
    return [];
  }
}

const statusRank = { potwierdzony: 2, niepotwierdzony: 1, plotka: 0 };

function mergeRound(oldR, newR) {
  if (!oldR) return newR;
  const oldRank = statusRank[oldR.status] ?? 0;
  const newRank = statusRank[newR.status] ?? 0;
  const isPlaceholder = d => !d || d === 'TBA' || d === 'TBD';
  const keepOldDate = !isPlaceholder(oldR.data) && oldRank >= newRank;
  return {
    gp: newR.gp || oldR.gp,
    tor: newR.tor || oldR.tor,
    data: keepOldDate ? oldR.data : (newR.data || oldR.data),
    status: newRank >= oldRank ? newR.status : oldR.status,
    info: newR.info || oldR.info
  };
}

const previousRounds = await getPreviousRounds();
const rawNewRounds = parsed.known_rounds || [];
rawNewRounds.forEach(r => { r.key = normalizeKey(r); });
previousRounds.forEach(r => { r.key = normalizeKey(r); });

const mergedRounds = rawNewRounds.map(newR => {
  const oldR = previousRounds.find(r => r.key === newR.key);
  return mergeRound(oldR, newR);
});
previousRounds.forEach(oldR => {
  if (!mergedRounds.find(r => r.key === oldR.key)) mergedRounds.push(oldR);
});

const changedAfterMerge = mergedRounds.filter(newR => {
  const oldR = previousRounds.find(r => r.key === newR.key);
  return !oldR || oldR.status !== newR.status || oldR.data !== newR.data;
});

const hasNew = changedAfterMerge.length > 0;
const points = parsed.new_summary_points || [];

const statusEmoji = { potwierdzony: '✅', niepotwierdzony: '⚠️', plotka: '❔' };

function renderBlock(r) {
  const emoji = statusEmoji[r.status] || '•';
  let block = `${emoji} *${r.gp}*\n📍 ${r.tor}\n📅 ${r.data}\n`;
  if (r.info) block += `ℹ️ ${r.info}\n`;
  return block;
}

const isWednesday = $now.setZone('Europe/Warsaw').weekday === 3;

let message = '';
let shouldSend = false;

if (isWednesday) {
  shouldSend = mergedRounds.length > 0;
  if (shouldSend) {
    message = '📅 *Cotygodniowe podsumowanie kalendarza MotoGP 2027:*\n\n';
    message += mergedRounds.map(renderBlock).join('\n');
  }
} else if (hasNew) {
  shouldSend = true;
  message = '🆕 *Nowe informacje o kalendarzu MotoGP 2027:*\n';
  message += points.length ? points.map(p => '• ' + p).join('\n') : changedAfterMerge.map(r => `• ${r.gp}: ${r.status}`).join('\n');
  message += '\n\n*Zaktualizowane rundy:*\n\n';
  message += changedAfterMerge.map(renderBlock).join('\n');
}

return [{
  json: {
    should_send: shouldSend,
    message_pl: message.trim(),
    known_rounds_json: JSON.stringify(mergedRounds)
  }
}];
